let pendingOtpTimer = null
let otpSending = false
// iOS drops a request started in the same tap that mounts or destroys a native input.
const otpSendDelay = uni.getSystemInfoSync().platform === 'ios' ? 300 : 0

function clearPendingOtpTimer() {
	if (!pendingOtpTimer) return
	clearTimeout(pendingOtpTimer)
	pendingOtpTimer = null
}

function onSendOtp() {
	if (pendingOtpTimer || otpSending || loginState.optTime) return
	optTimeFn()
}

async function optTimeFn() {
	if (otpSending || loginState.optTime) return
	otpSending = true
	try {
		//发送验证码
		await sendHPOtp({
			contact: `${loginState.areaCode[loginState.actionIndex].name}-${loginState.form.phone}`,
			lang: locale.value,
			verifyExistingContact: false,
		})
		if (!loginState.isOTP) return
		loginState.optTime = 60;
		function start () {
			loginState.optTime = loginState.optTime - 1;
			if(loginState.optTime) {
				loginState.timer = setTimeout(start, 1000);
			} else {
				clearTimeout(loginState.timer)
			}
		}
		start();
	} finally {
		otpSending = false
	}
}

function changeOTP() {
	if (!loginState.form.phone) {
		//填写手机号
		uni.showToast({
			icon: 'none',
			title: t('请先填写手机号')
		})
		return
	}
	clearPendingOtpTimer()
	loginState.isOTP = !loginState.isOTP;
	if (loginState.isOTP) {
		uni.hideKeyboard()
		uni.nextTick(() => {
			pendingOtpTimer = setTimeout(() => {
				pendingOtpTimer = null
				if (!loginState.isOTP) return
				optTimeFn()
			}, otpSendDelay)
		})
	} else {
		loginState.timer && clearTimeout(loginState.timer);
	}
}

