() => {
  const clean = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const menus = Array.from(document.querySelectorAll('.weui-desktop-dropdown__list, .dropdown_menu, .js_dropdown, [role="menu"], .weui-desktop-dropdown-menu, ul'));
  const visible = menus.map(el => {
    const r = el.getBoundingClientRect();
    const style = getComputedStyle(el);
    const shown = r.width > 0 && r.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
    return { shown, text: clean(el.innerText).slice(0, 300), cls: el.className.toString().slice(0, 120) };
  }).filter(x => x.shown && x.text && (x.text.includes('体验') || x.text.includes('删除') || x.text.includes('审核')));
  return { visible: visible.slice(0, 8) };
}

